function collectLinearTeams({ previousState, response }) {
  const state = previousState
    ? { teams: [...previousState.teams], cursors: [...previousState.cursors] }
    : { teams: [], cursors: [] };
  if (response !== undefined && response !== null) {
    if (Array.isArray(response.errors) && response.errors.length)
      throw new Error("Linear team query failed.");
    const connection = response.data?.teams,
      info = connection?.pageInfo;
    if (
      !connection ||
      !Array.isArray(connection.nodes) ||
      connection.nodes.some(
        (t) => !t || typeof t.id !== "string" || !t.id || typeof t.name !== "string",
      ) ||
      !info ||
      typeof info.hasNextPage !== "boolean"
    )
      throw new Error("Invalid Linear team page.");
    state.teams.push(...connection.nodes);
    if (!info.hasNextPage) return { state, more: false, after: null };
    if (
      typeof info.endCursor !== "string" ||
      !info.endCursor ||
      state.cursors.includes(info.endCursor)
    )
      throw new Error("Linear team pagination did not advance.");
    state.cursors.push(info.endCursor);
    return { state, more: true, after: info.endCursor };
  }
  if (previousState) throw new Error("Missing next Linear team page.");
  return { state, more: true, after: null };
}

return [{ json: collectLinearTeams({}), pairedItem: { item: 0 } }];

