function confirmedLinearMove({ issue, issueId, teamId, classification }) {
  if (!issue || issue.id !== issueId || issue.team?.id !== teamId)
    throw new Error(
      "Linear did not confirm the requested team move; inspect the issue before replay.",
    );
  return { result: { status: "moved", issueId, teamId, classification, issue } };
}
function confirmedLinearFallback({ ts, channelId, expectedChannelId, issueId, classification }) {
  if (typeof ts !== "string" || !ts || channelId !== expectedChannelId)
    throw new Error(
      "Slack did not confirm the fallback notification; inspect the channel before replay.",
    );
  return {
    result: { status: "notified", issueId, classification, notification: { ts, channelId } },
  };
}

const response = $input.first().json,
  payload = response.data?.issueUpdate;
if (response.errors?.length || payload?.success !== true)
  throw new Error("Linear did not confirm the team update; inspect before replay.");
return [
  {
    json: confirmedLinearMove({
      issue: payload.issue,
      ...$("Resolve exact team name").first().json,
    }),
    pairedItem: { item: 0 },
  },
];

function confirmedLinearMove({ issue, issueId, teamId, classification }) {
  if (!issue || issue.id !== issueId || issue.team?.id !== teamId)
    throw new Error(
      "Linear did not confirm the requested team move; inspect the issue before replay.",
    );
  return { result: { status: "moved", issueId, teamId, classification, issue } };
}
function confirmedLinearFallback({ ts, channelId, expectedChannelId, issueId, classification }) {
  if (typeof ts !== "string" || !ts || channelId !== expectedChannelId)
    throw new Error(
      "Slack did not confirm the fallback notification; inspect the channel before replay.",
    );
  return {
    result: { status: "notified", issueId, classification, notification: { ts, channelId } },
  };
}

const receipt = $input.first().json,
  plan = $("Resolve exact team name").first().json;
return [
  {
    json: confirmedLinearFallback({
      ts: receipt.ts,
      channelId: receipt.channel ?? receipt.channelId,
      expectedChannelId: $("Set me up").first().json.slackChannel,
      ...plan,
    }),
    pairedItem: { item: 0 },
  },
];

return [
  {
    json: {
      result: { status: "skipped", event: $("Prepare complete Linear event").first().json.event },
    },
    pairedItem: { item: 0 },
  },
];
